/**
 * The icons of the installable web app (FE-H2), made from the store icons in
 * store-assets/app-icon/ (themselves generated by make-app-icons.py), so the
 * home-screen icon is the same "GO" as the phone app's. Run it again after the
 * store icons change:
 *
 *   node scripts/brand/make-web-app-icons.mjs
 *
 * - icon-192.png, icon-512.png: the Play Store icon (opaque, rounded by the
 *   phone), at the two sizes browsers ask for.
 * - icon-maskable-512.png: the Android adaptive icon's background and
 *   foreground layers, stacked. The mark already sits inside the adaptive
 *   icon's safe circle (66 of 108), well within the maskable safe zone (80%),
 *   so no phone's icon shape cuts it.
 */
import sharp from "sharp";

const source = new URL("../../store-assets/app-icon/android/", import.meta.url);
const out = new URL("../../public/icons/", import.meta.url);
const file = (base, name) => new URL(name, base).pathname;

const store = file(source, "play-store-icon-512.png");
await sharp(store).resize(192, 192).png({ compressionLevel: 9 }).toFile(file(out, "icon-192.png"));
await sharp(store).resize(512, 512).png({ compressionLevel: 9 }).toFile(file(out, "icon-512.png"));

const foreground = await sharp(file(source, "adaptive-foreground-432.png"))
  .resize(512, 512)
  .toBuffer();
await sharp(file(source, "adaptive-background-432.png"))
  .resize(512, 512)
  .composite([{ input: foreground }])
  .png({ compressionLevel: 9 })
  .toFile(file(out, "icon-maskable-512.png"));

console.log("public/icons: icon-192.png, icon-512.png, icon-maskable-512.png");
